const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '4:1' }];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = w * 0.12;
    var x1 = w * 0.88;
    var y = h * 0.58;
    var xdiv = x0 + (x1 - x0) * 0.8;
    var tick = Math.max(8, h * 0.06);
    var segment = visualSdk.polyline([[x0, y], [x1, y]]);
    var tickStart = visualSdk.polyline([[x0, y - tick], [x0, y + tick]]);
    var tickDiv = visualSdk.polyline([[xdiv, y - tick], [xdiv, y + tick]]);
    var tickEnd = visualSdk.polyline([[x1, y - tick], [x1, y + tick]]);
    return {
      schemaVersion: 1,
      sceneId: 'ratio-4-to-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'segment', commands: segment },
        { id: 'tick-start', commands: tickStart },
        { id: 'tick-div', commands: tickDiv },
        { id: 'tick-end', commands: tickEnd }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'tick-start', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'tick-div', fill: '#c0392b', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'tick-end', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: (x0 + x1) / 2, y: Math.max(16, y - tick - 12) }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
        ]
      }
    };
  }
};
